  public executeTrade(agentId: string, tradeId: string, currentTime: bigint): { status: 'executed' | 'rejected'; reason?: string } {
    try {
      const maxPos = this.witnesses.getMaxPositionPct();
      const stopLoss = this.witnesses.getStopLossPct();
      const expiry = this.witnesses.getStrategyExpiry();

      const recomputedHash = this.calculateStrategyHash(maxPos, stopLoss, expiry);
      const committedHash = this.agentCommitment.get(agentId);

      if (!committedHash || committedHash !== recomputedHash) {
        this.tradeStatus.set(tradeId, 2); // Rejected
        throw new Error('trade does not match committed strategy');
      }

      if (currentTime > expiry) {
        this.tradeStatus.set(tradeId, 2);
        throw new Error('strategy timeline expired');
      }

      const tradeSize = this.witnesses.getTradeSizeUsd();
      const portfolioVal = this.witnesses.getPortfolioValue();
      if (portfolioVal === 0n) {
        this.tradeStatus.set(tradeId, 2);
        throw new Error('invalid portfolio value');
      }

      const positionPct = (tradeSize * 100n) / portfolioVal;
      if (positionPct > BigInt(maxPos)) {
        this.tradeStatus.set(tradeId, 2);
        throw new Error('exceeds max position size');
      }

      const riskCheckPassed = this.witnesses.getRiskCheckPassed ? this.witnesses.getRiskCheckPassed() : true;
      if (!riskCheckPassed) {
        this.tradeStatus.set(tradeId, 2);
        throw new Error('risk model check failed');
      }

      // Success
      this.tradeStatus.set(tradeId, 1);
      this.tradeCount++;
      return { status: 'executed' };
    } catch (err: any) {
      return { status: 'rejected', reason: err.message };
    }
  }

